 {workflow:'streaks',id:'streaks_tray',title:'Clear the tablet collecting tray',text:'Arrange the top basket so tableware does not block the detergent dispenser lid, and keep tableware and fragrance dispensers out of the tablet collecting tray.',pages:[44,27]},
 {workflow:'streaks',id:'streaks_prerinse',title:'Avoid intensive pre-rinsing',text:'Remove only large food remnants before loading; do not pre-rinse the tableware.',pages:[45]}
